from pathlib import Path
import sys,json
H=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parent
data={g:json.loads((H/f'{g}-manifest.json').read_text(encoding='utf-8')) for g in ['bare','helmet']}
options=''.join(f'<option value="{s["id"]}">{s["id"].removeprefix("swim-carry-turn-")}</option>' for s in data['bare']['states'])
html='''<!doctype html><meta charset="utf-8"><title>Veld paired cargo turn review</title><style>body{background:#202a30;color:#e5ebed;font:16px sans-serif;margin:24px}a{color:#8cc6e7}canvas,img{max-width:100%;height:auto}button,select,input{margin:8px}</style><h1>Veld — cargo turn and master endpoints</h1><p>Finite800ms turn, paired bare/helmet on one clock. Exact cargo endpoints. Staged; world routes and full-family motion review remain.</p><label>Direction<select id="direction">OPTIONS</select></label><button id="play">Replay</button><label>Frame<input id="phase" aria-label="Frame" type="range" min="0" max="5" value="0"></label><label>Speed<select id="speed"><option value="1">Full speed</option><option value="0.3333333333">One-third speed</option></select></label><label>Background<select id="bg"><option value="#202a30">Dark</option><option value="#a7afb2">Light</option></select></label><span id="clock"></span><canvas id="board" width="1050" height="640"></canvas><p><a href="native-candidate-v1.png">Native frame board</a> · <a href="source-provenance.json">Raw source selection and exact prompts</a></p><img src="bare-contact-v1.png"><img src="helmet-fit-contact-v1.png"><script>const data=DATA;let running=false,elapsed=0,last=performance.now(),images={};const ctx=board.getContext('2d');async function init(){for(const g of ['bare','helmet']){images[g]={};for(const s of data[g].states){images[g][s.id]=await Promise.all(s.frameFiles.map(url=>new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(url);im.src=url})))}}requestAnimationFrame(tick)}function selection(){const s=data.bare.states.find(s=>s.id===direction.value);let e=elapsed;for(let i=0;i<6;i++){if(e<s.frameDurationsMs[i])return i;e-=s.frameDurationsMs[i]}return 5}function draw(){const i=selection();phase.value=i;ctx.fillStyle=bg.value;ctx.fillRect(0,0,1050,640);ctx.fillStyle=bg.value==='#202a30'?'#e5ebed':'#202a30';ctx.font='16px sans-serif';for(let j=0;j<2;j++){const g=j?'helmet':'bare',row=images[g][direction.value],im=row[i],y=j*320;ctx.fillText(g+' / phase'+i,8,y+20);for(const [size,x,label] of [[256,20,'148 ruler'],[142,280,'82 ruler'],[93,450,'54 ruler']]){ctx.drawImage(im,x,y+35,size,size);ctx.fillText(label,x,y+300)}ctx.drawImage(row[0],590,y+70,142,142);ctx.drawImage(row[5],800,y+70,142,142);ctx.fillText('source cargo master',590,y+260);ctx.fillText('destination cargo master',800,y+260)}clock.textContent=Math.round(elapsed)+' /800ms'}function tick(t){if(running){elapsed=Math.min(800,elapsed+(t-last)*Number(speed.value));if(elapsed===800){running=false;play.textContent='Replay'}}last=t;draw();requestAnimationFrame(tick)}play.onclick=()=>{if(running){running=false;play.textContent='Replay'}else{elapsed=0;running=true;play.textContent='Pause'}};direction.onchange=()=>{elapsed=0;running=false;play.textContent='Replay';draw()};phase.oninput=e=>{running=false;play.textContent='Replay';const s=data.bare.states.find(s=>s.id===direction.value);elapsed=s.frameDurationsMs.slice(0,Number(e.target.value)).reduce((a,b)=>a+b,0);draw()};init().catch(e=>clock.textContent='Missing frame '+e)</script>'''
(H/'index.html').write_text(html.replace('OPTIONS',options).replace('DATA',json.dumps(data)),encoding='utf-8')
print('Finite paired forward/reverse master review saved.')
